package main

import (
	"bufio"
	"fmt"
	"os"
)

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func max(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func lucky(i int) int64 {
	if i == 1 {
		return 0
	}
	lastDigit := int64(7)
	if i%2 == 0 {
		lastDigit = 4
	}
	return lucky(i/2)*10 + lastDigit
}

func main() {
	var l, r int64
	fmt.Fscan(bufio.NewReader(os.Stdin), &l, &r)

	aa := make([]int64, 2047)
	aa[0] = 4
	for i := 1; i < 2047; i++ {
		aa[i] = lucky(i + 1)
	}

	var ans int64
	for i := 0; i < 2047; i++ {
		var prev int64
		if i > 0 {
			prev = aa[i-1]
		}
		x := max(prev+1, l)
		y := min(aa[i], r)
		if x <= y {
			ans += (y - x + 1) * aa[i]
		}
	}
	fmt.Println(ans)
}

